loadstring([=[
local K = {166,35,87,100,212,24,165}
local s = [[]]
local function d(s)
	local n = #s / 3
	local out = {}
	for j = 0, n - 1 do
		local p = 3 * j + 1
		local c = tonumber(s:sub(p, p + 2))
		local bi = n - 1 - j
		out[bi + 1] = string.char((c ~ K[(bi % #K) + 1]) % 256)
	end
	return table.concat(out)
end
if not game then error("invalid environment") end
local f = loadstring or load
if not f then error("no loader") end
local fn, err = f(d(s))
if not fn then error("decode error: " .. tostring(err)) end
fn()
]=])()
